# -*- coding: utf-8 -*-
"""Lote 1 · parte D: cardiología, tórax y vascular (preguntas 53-78)."""
from lote01c import Q, L

Q(a="ciencias_basicas", cat="Fisiología", tema="Fases del ciclo cardiaco", año=2015, ext=False,
  e="¿Cuál de las siguientes fases NO forma parte del ciclo cardíaco?",
  o=["Llenado.", "Relajación isobarométrica.", "Contracción isovolumétrica.", "Eyección.", "Relajación isovolumétrica."], k="B",
  c="El ciclo cardiaco se divide en sístole y diástole. La sístole ventricular comprende la contracción isovolumétrica (todas las válvulas cerradas, la presión sube sin cambio de volumen), la eyección rápida y la eyección lenta. La diástole comprende la relajación isovolumétrica (la presión cae con las válvulas cerradas), el llenado rápido, el llenado lento o diástasis y la contracción auricular, que aporta el 15-25 % del llenado. «Relajación isobarométrica» no es una fase del ciclo: es una trampa que cambia «volumétrica» por «barométrica». Dato útil: el primer ruido cardiaco corresponde al cierre de las válvulas auriculoventriculares (inicio de la contracción isovolumétrica) y el segundo al cierre de las sigmoideas aórtica y pulmonar (inicio de la relajación isovolumétrica). En la fibrilación auricular se pierde la contracción auricular, y un paciente con estenosis mitral o rigidez ventricular lo siente más.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Berne y Levy Fisiología 7.ª ed.")

Q(a="cardiologia", cat=None, tema="Inhibidor directo de la renina", año=2015, ext=False,
  e="Los inhibidores directos de la renina son una clase novedosa de antihipertensivos que inhiben al sistema renina-angiotensina (SRA) en su origen. Un ejemplo de estos fármacos es:",
  o=["Enalaprilato.", "Telmisartán.", "Ramipril.", "Aliskiren.", "Valsartán."], k="D",
  c="El aliskiren es el único inhibidor directo de la renina disponible: se une a la renina e impide la conversión del angiotensinógeno en angiotensina I, el paso inicial del sistema renina-angiotensina-aldosterona. Enalaprilato y ramipril son inhibidores de la enzima convertidora de angiotensina (IECA, terminan en «-pril»), y telmisartán y valsartán son antagonistas del receptor de angiotensina II (ARA II, terminan en «-sartán»). El aliskiren se aprobó en 2007, pero el ensayo ALTITUDE mostró más eventos adversos al combinarlo con IECA o ARA II en diabéticos con enfermedad renal, por lo que no se debe asociar a ellos en diabéticos ni en insuficiencia renal. Hoy ocupa un lugar marginal en las guías y se evita en el embarazo, como todo fármaco que bloquea el SRAA (riesgo de fetopatía).",
  f="ACC/AHA, guía de hipertensión arterial (2025); Katzung Farmacología Básica y Clínica 15.ª ed.; ensayo ALTITUDE (NEJM 2012)")

Q(a="cardiologia", cat=None, tema="Criterios de endocarditis infecciosa", año=2015, ext=False,
  e="¿Cuál de los siguientes hallazgos es un criterio importante (mayor) para el diagnóstico de endocarditis infecciosa?",
  o=["Cardiomegalia en la radiografía de tórax.", "Fiebre de 38 °C por más de dos semanas.", "Hemocultivo positivo.", "Urocultivo positivo.", "Antecedente de cateterismo cardiaco."], k="C",
  c="El diagnóstico de endocarditis infecciosa se basa en los criterios de Duke, actualizados en 2023 por la ISCVID (Duke-ISCVID). Criterios mayores: evidencia microbiológica (hemocultivos positivos para microorganismos típicos, como Staphylococcus aureus, estreptococos viridans, enterococos y grupo HACEK, en al menos dos muestras separadas) y evidencia de afectación endocárdica por imagen (ecocardiografía, TC cardiaca o PET-TC con vegetación, absceso o dehiscencia protésica) o hallazgos quirúrgicos. Criterios menores: factor predisponente (válvula protésica, cardiopatía congénita, uso de drogas intravenosas, dispositivos), fiebre ≥ 38 °C, fenómenos vasculares (embolias, aneurismas micóticos, lesiones de Janeway), inmunológicos (nódulos de Osler, manchas de Roth, glomerulonefritis, factor reumatoide) y evidencia microbiológica que no cumple el criterio mayor. Se necesitan 2 mayores, 1 mayor + 3 menores o 5 menores. Se toman al menos tres sets de hemocultivos antes del antibiótico.",
  f="Duke-ISCVID, criterios 2023 (Fowler et al., Clin Infect Dis 2023); ESC, guía de endocarditis infecciosa (2023); Braunwald Tratado de Cardiología 12.ª ed.",
  nota="La clave original tenía dos respuestas válidas (hemocultivo y ecocardiografía, ambos mayores); se reemplazaron A y D para dejar una sola.")

Q(a="cirugia", cat=None, tema="Hemotórax: relación de hematocritos", año=2015, ext=False,
  e="El líquido pleural obtenido por toracocentesis tiene características hemáticas. ¿Cuál es la relación en % entre el hematocrito del líquido pleural y la sangre periférica, para confirmar diagnóstico de hemotórax?",
  o=["> 50.", "> 45.", "> 30.", "> 10.", "> 20."], k="A",
  c="Un derrame pleural sanguinolento no es siempre un hemotórax: con apenas 1 mL de sangre por litro de líquido pleural se ve rojizo. El hemotórax se define cuando el hematocrito del líquido pleural es igual o mayor al 50 % del hematocrito de la sangre periférica (relación > 0,5). Entre el 1 y el 50 % se habla de derrame pleural hemorrágico (neoplasia, embolia pulmonar, tuberculosis, trauma leve). La causa más frecuente de hemotórax es el traumatismo torácico penetrante o cerrado. Tratamiento: toracostomía con tubo grueso (≥ 28-32 Fr); toracotomía si la salida inicial es mayor de 1500 mL o continúa > 200 mL/h durante 2-4 horas, o si hay inestabilidad hemodinámica. El hemotórax residual se maneja con toracoscopía (VATS) para evitar empiema y atrapamiento pulmonar.",
  f="ATLS, 11.ª ed. (2025); EAST, guía de hemotórax (Mowery 2011); Light Pleural Diseases 6.ª ed.")

Q(a="cardiologia", cat=None, tema="Marcador de elección en el infarto agudo", año=2015, ext=False,
  e="¿Cuál es el marcador de elección en el infarto agudo de miocardio en emergencia?",
  o=["Mioglobina.", "Troponina.", "CPK-MB.", "Transaminasa oxalacética.", "Deshidrogenasa láctica."], k="B",
  c="La troponina cardiaca (I o T), preferiblemente de alta sensibilidad, es el biomarcador de elección para el diagnóstico de infarto: es específica del miocardio, se eleva a las 2-3 horas y su valor aumenta o disminuye en mediciones seriadas (0-1 h o 0-2 h con algoritmos de la ESC). Una troponina normal a las 3 horas del inicio del dolor, con ECG normal y baja probabilidad clínica, descarta el infarto con alto valor predictivo negativo. La CPK-MB es menos específica; la mioglobina es precoz pero poco específica; la transaminasa oxalacética (AST) y la LDH son obsoletas. Si el ECG muestra elevación del ST (STEMI) no se espera la troponina para reperfundir. Recuerda que troponina elevada no siempre es infarto tipo 1: aparece en miocarditis, embolia pulmonar, insuficiencia renal, sepsis y falla cardiaca (tipo 2 o daño miocárdico).",
  f="ESC, síndromes coronarios agudos (2023); AHA/ACC, dolor torácico (2021); Cuarta Definición Universal del Infarto (2018)")

Q(a="cardiologia", cat=None, tema="Infarto inferior con bradicardia e hipotensión", año=2015, ext=False,
  e="Varón de 53 años, hipertenso, diabético y obeso, con tratamiento irregular. Ingresa a Emergencia con cuadro de dolor torácico, diaforesis e inestabilidad hemodinámica. Al examen físico: PA: 80/60 mm Hg, FC: 50 x min. Electrocardiograma: elevación del ST en II, III y aVF. ¿Cuál es el diagnóstico más probable?",
  o=["Infarto de miocardio de cara inferior.", "Bloqueo completo de rama derecha del haz de His.", "Infarto de miocardio de cara lateral.", "Pericarditis aguda.", "Infarto de miocardio de cara anterior."], k="A",
  c="La elevación del ST en II, III y aVF corresponde a la cara inferior del ventrículo izquierdo, irrigada por la coronaria derecha en el 80 % (dominancia derecha) o por la circunfleja. La bradicardia y la hipotensión se explican porque la coronaria derecha irriga el nodo sinusal y el nodo AV (bradicardia sinusal, bloqueo AV) y por reflejo de Bezold-Jarisch (activación vagal por isquemia inferior). Siempre se debe registrar V3R-V4R y V4R: la elevación del ST en V4R indica infarto del ventrículo derecho, que se trata con volumen y se contraindican nitratos y diuréticos. La reperfusión urgente (angioplastia primaria < 120 minutos) es obligatoria. Las derivaciones: septal V1-V2, anterior V3-V4, lateral I, aVL, V5-V6, inferior II, III, aVF; el infarto posterior se ve como depresión del ST en V1-V3.",
  f="ESC, síndromes coronarios agudos (2023); AHA/ACC, guía de revascularización (2021); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cirugia", cat=None, tema="Trauma torácico penetrante con hemotórax", año=2015, ext=False,
  e="Varón de 18 años, que ha sufrido hace 30 minutos herida por bala, manifiesta dolor y dificultad para respirar. Examen: PA: 90/60 mm Hg, FR: 30 x min, FC: 100 x min, herida de ingreso en cara posterior de hemitórax derecho. Murmullo vesicular abolido en el hemitórax derecho. Rx de tórax: imagen radiopaca en el tercio inferior y pulmón colapsado. Mediastino normal. ¿Cuál de las siguientes medidas se debe tomar de inmediato?",
  o=["Transfusión sanguínea.", "Drenaje torácico.", "Toracotomía.", "Toracocentesis.", "Esternotomía media."], k="B",
  c="Un paciente con herida por proyectil de arma de fuego, dificultad respiratoria, murmullo abolido y velamiento del tercio inferior con pulmón colapsado tiene un hemotórax traumático (con neumotórax asociado, hemoneumotórax). La medida inicial y terapéutica en la sala de shock trauma es el drenaje torácico (toracostomía con tubo) de calibre grueso, que evacua la sangre y reexpande el pulmón; además se repone volumen con cristaloides y hemoderivados según la respuesta. Se indica toracotomía si el drenaje inicial es de más de 1500 mL, el débito persiste en más de 200 mL por hora durante 2-4 horas, o el paciente se inestabiliza. La toracocentesis simple es insuficiente y la esternotomía se reserva para lesiones mediastínicas. La secuencia ATLS es ABCDE: vía aérea, ventilación, circulación (acceso venoso y control del sangrado), discapacidad y exposición.",
  f="ATLS, 11.ª ed. (2025); EAST, guía de hemotórax (Mowery 2011); Schwartz Principios de Cirugía 11.ª ed.")

Q(a="neumologia", cat=None, tema="Tumor más frecuente del mediastino en el adulto", año=2015, ext=False,
  e="¿Cuál es la tumoración más frecuente que se presenta en el mediastino del adulto?",
  o=["Tumor neurogénico.", "Tumor de células germinales.", "Linfoma.", "Timoma.", "Quiste no tímico."], k="D",
  c="Los tumores mediastínicos se ubican por compartimentos: el mediastino anterosuperior concentra las «4 T» (timoma, teratoma o tumor germinal, tiroides o bocio endotorácico, «terrible» linfoma), el medio los quistes broncogénicos y pericárdicos y los ganglios, y el posterior los tumores neurogénicos (schwannoma, neurofibroma). En el adulto la masa mediastínica primaria más frecuente del mediastino anterior es el timoma, que representa casi la mitad de los casos de esa localización; se asocia a miastenia gravis en 30-50 % (y al revés, el 10-15 % de los miasténicos tienen timoma), aplasia pura de serie roja e hipogammaglobulinemia. En el niño predominan los tumores neurogénicos. Diagnóstico: TC de tórax con contraste y biopsia guiada, evitando biopsiar el timoma resecable. Tratamiento del timoma: resección completa; la radioterapia o quimioterapia se emplean en estadios avanzados.",
  f="ESMO-EURACAN, tumores epiteliales tímicos (2021); Harrison Principios de Medicina Interna 22.ª ed.; Shields Thoracic Surgery 8.ª ed.")

Q(a="cirugia", cat=None, tema="Tratamiento conservador de la tromboflebitis superficial", año=2015, ext=False,
  e="¿Cuál es la medida conservadora que ayuda al tratamiento de la tromboflebitis superficial?",
  o=["Colocación de compresas calientes.", "Elevación de las extremidades.", "Evitar ingesta de AINES.", "Uso de anticoagulantes.", "Uso de medidas elásticas."], k="B",
  c="La tromboflebitis superficial es una inflamación y trombosis de una vena superficial, típicamente sobre várices, con dolor, eritema, calor y un cordón indurado palpable. El tratamiento conservador consiste en elevar la extremidad, aplicar calor local o compresas tibias, deambular y usar AINES tópicos u orales por periodos cortos para el dolor. Las medias elásticas ayudan a largo plazo, aunque la compresión no se coloca sobre la zona dolorosa en la fase aguda. El anticoagulante (fondaparinux 2,5 mg/día por 45 días) está indicado si el trombo mide ≥ 5 cm, está a menos de 3 cm de la unión safenofemoral o hay factores de riesgo; si el trombo toca la unión safenofemoral se trata como trombosis venosa profunda. Siempre se debe descartar trombosis venosa profunda con eco Doppler.",
  f="ACCP/CHEST, tratamiento de la trombosis venosa (2021); ESVS, guía de enfermedad venosa (2022); estudio CALISTO (NEJM 2010)",
  nota="La respuesta del libro es B (elevación); en la clínica, compresas tibias y AINE también son medidas aceptadas, y se prefiere la elevación como la única de la lista que no tiene contraindicación.")

Q(a="ciencias_basicas", cat="Farmacología básica y autonómica", tema="Adrenalina en dosis altas", año=2016, ext=False,
  e="El aumento de presión arterial secundario a la administración rápida de dosis altas de adrenalina endovenosa se produce debido a...",
  o=["Predominancia del efecto alfa-1 adrenérgico.", "Efecto inotrópico negativo directo.", "Disminución de la frecuencia cardiaca.", "Vasodilatación venosa.", "Vasodilatación de las arterias coronarias."], k="A",
  c="La adrenalina actúa sobre receptores alfa-1, alfa-2, beta-1 y beta-2 con afinidad dosis-dependiente. En dosis bajas predomina el efecto beta (aumento de frecuencia y contractilidad, vasodilatación muscular beta-2); en dosis altas o en bolo rápido predomina la vasoconstricción arterial por receptores alfa-1, que eleva la resistencia vascular sistémica y la presión arterial. Por eso en el paro cardiorrespiratorio se usa 1 mg IV cada 3-5 minutos: la vasoconstricción aumenta la presión de perfusión coronaria y cerebral durante la reanimación. En la anafilaxia se usa 0,3-0,5 mg IM en la cara anterolateral del muslo, que revierte la broncoconstricción y el colapso. Efectos adversos: arritmias, hipertensión grave, isquemia miocárdica y necrosis tisular por extravasación (se trata con fentolamina).",
  f="AHA, Soporte Vital Cardiovascular Avanzado (actualización 2025); WAO, guía de anafilaxia (2020); Katzung Farmacología Básica y Clínica 15.ª ed.")

Q(a="cardiologia", cat=None, tema="Soplo de la insuficiencia mitral", año=2016, ext=False,
  e="¿Cuál es el tipo de soplo que caracteriza a la insuficiencia mitral?",
  o=["Holosistólico de tono alto en ápex, irradiado a axila.", "Sistólico eyectivo de timbre rudo, irradiado al cuello.", "Mesodiastólico regurgitativo con chasquido de apertura.", "Diastólico aspirativo irradiado a borde paraesternal izquierdo.", "Holosistólico suave, paraesternal izquierdo y subxifoideo."], k="A",
  c="La insuficiencia mitral produce un soplo holosistólico (pansistólico) soplante de tono alto, mejor audible en el ápex y que se irradia a la axila izquierda; se acompaña de primer ruido disminuido y, si es grave, tercer ruido y soplo mesodiastólico de flujo. La estenosis aórtica da un soplo sistólico eyectivo rudo irradiado a las carótidas; la estenosis mitral, un retumbo mesodiastólico con chasquido de apertura; la insuficiencia aórtica, un soplo diastólico aspirativo decreciente en el borde esternal izquierdo, y la comunicación interventricular, un soplo holosistólico en el borde esternal izquierdo. Las maniobras ayudan: el soplo de la insuficiencia mitral aumenta con el esfuerzo isométrico (handgrip) y no con la inspiración. Causas: prolapso, degenerativa, isquemia (rotura de músculo papilar) y endocarditis.",
  f="ACC/AHA, guía de valvulopatías (2020); ESC/EACTS (2021); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Causa cardiaca más frecuente de embolia", año=2016, ext=False,
  e="¿Cuál es la causa más frecuente de embolia de origen cardíaco?",
  o=["Fibrilación auricular.", "Infarto agudo de miocardio.", "Miocardiopatía dilatada.", "Endocarditis infecciosa subaguda.", "Insuficiencia aórtica."], k="A",
  c="La fibrilación auricular es la causa más frecuente de embolia de origen cardiaco y de ictus cardioembólico (alrededor del 50 % de los cardioembolismos). La contracción auricular ineficaz favorece la estasis y la formación de trombos en la orejuela izquierda. El riesgo de ictus se estima con la escala CHA₂DS₂-VASc (insuficiencia cardiaca, hipertensión, edad ≥ 75 años = 2 puntos, diabetes, ictus previo = 2, enfermedad vascular, edad 65-74, sexo femenino); se anticoagula con ≥ 2 puntos en varones y ≥ 3 en mujeres. Los anticoagulantes orales directos (apixabán, rivaroxabán, edoxabán, dabigatrán) se prefieren a la warfarina, excepto en estenosis mitral reumática moderada-grave o prótesis mecánicas, donde se usa warfarina. Otras fuentes de embolia: infarto con trombo apical, miocardiopatía dilatada, endocarditis y mixoma auricular.",
  f="ESC/EACTS, guía de fibrilación auricular (2024); AHA/ACC/HRS, guía de fibrilación auricular (2023)")

Q(a="cardiologia", cat=None, tema="Infarto lateral: derivaciones del ECG", año=2016, ext=False,
  e="¿En qué derivaciones del EKG se observan las alteraciones de un infarto lateral de miocardio?",
  o=["DI, aVL.", "V1, V2.", "V3, V4.", "DI, V1.", "DII, aVF."], k="A",
  c="Las derivaciones del ECG se relacionan con la pared del corazón que «miran»: septal V1-V2 (descendente anterior), anterior V3-V4 (descendente anterior), lateral baja V5-V6 y lateral alta DI y aVL (arteria circunfleja o diagonales), e inferior DII, DIII y aVF (coronaria derecha en el 80 %). El infarto lateral alto se manifiesta por elevación del ST en DI y aVL, con imagen en espejo (depresión del ST) en las derivaciones inferiores. La circunfleja también puede ocluirse sin cambios evidentes en el ECG de 12 derivaciones (zona «silenciosa»), por lo que se añaden las derivaciones posteriores V7-V9 si hay sospecha. Una elevación del ST de al menos 1 mm en dos derivaciones contiguas, o ≥ 2 mm en V2-V3 en varones, define el infarto con elevación del ST (STEMI).",
  f="ESC, síndromes coronarios agudos (2023); Cuarta Definición Universal del Infarto (2018); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="ciencias_basicas", cat="Fisiología", tema="Síntesis del péptido natriurético atrial", año=2016, ext=False,
  e="¿Dónde se sintetiza la hormona cardionatrina?",
  o=["Miocardio.", "Epicardio.", "Endocardio.", "Subendotelio.", "Pericardio."], k="A",
  c="La cardionatrina o péptido natriurético atrial (ANP) se sintetiza y almacena en gránulos de los miocitos auriculares, sobre todo de la aurícula derecha, y se libera cuando la distensión de la pared auricular aumenta por sobrecarga de volumen. Sus acciones: natriuresis y diuresis (aumenta la tasa de filtración glomerular y antagoniza la aldosterona), vasodilatación, inhibición de la renina y del tono simpático, y reducción del retorno venoso y de la presión arterial. El péptido natriurético cerebral (BNP) se produce en los ventrículos y su fragmento NT-proBNP es el biomarcador de insuficiencia cardiaca: valores < 300 pg/mL descartan insuficiencia cardiaca aguda. El sacubitrilo (en la combinación sacubitrilo/valsartán o ARNI) inhibe la neprilisina, que degrada los péptidos natriuréticos, y mejora la supervivencia en insuficiencia con FE reducida.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; ESC, insuficiencia cardiaca (2021, actualización 2023)")

Q(a="cardiologia", cat=None, tema="Conducta inicial en hipertensión arterial grado 2", año=2016, ext=False,
  e="Varón de 48 años con antecedente de tabaquismo, refiere cefaleas esporádicas desde hace 5 años, se automedica con analgésicos. Desde hace 3 meses las cefaleas son constantes y se acompañan de mareos e insomnio. Examen: lúcido, colaborador, IMC: 32, PA: 150/100 mmHg, FC: 85 x min. Cardiovascular: ruidos cardiacos rítmicos regulares y sin soplos. Resto de examen físico sin alteraciones. ¿Cuál es la conducta terapéutica inicial?",
  o=["Cambios en los estilos de vida.", "Solo monoterapia antihipertensiva.", "Iniciar terapia combinada antihipertensiva.", "Uso de antiagregantes plaquetarios.", "Uso de hipolipemiantes."], k="C",
  c="Una PA de 150/100 mmHg confirmada corresponde a hipertensión grado 2 (≥ 140/90, estadio 2 de la guía ACC/AHA) en un paciente con tabaquismo y obesidad, es decir, de riesgo cardiovascular elevado. Las guías actuales (ACC/AHA 2025, ESC 2024) recomiendan iniciar tratamiento farmacológico desde el primer momento, preferentemente con combinación en una sola pastilla (IECA o ARA II + calcioantagonista o tiazida), porque logra el control más rápido y mejora la adherencia, y añadir cambios del estilo de vida (dejar de fumar, bajar de peso, dieta DASH con baja sal, ejercicio). Los cambios del estilo de vida solos se reservan para el grado 1 de bajo riesgo. Antes de tratar se descartan causas secundarias si hay datos de alarma, y se evalúa daño de órgano (creatinina, albuminuria, ECG, fondo de ojo). Las metas son PA < 130/80 mmHg.",
  f="ACC/AHA, guía de hipertensión arterial (2025); ESC, guía de hipertensión arterial (2024)",
  nota="Clave del libro: A (estilos de vida). Se corrige a C por guías 2024-2025: grado 2 con riesgo cardiovascular alto se trata con combinación desde el inicio.")

Q(a="neumologia", cat=None, tema="Diagnóstico por imagen de bronquiectasias", año=2016, ext=False,
  e="¿Cuál es el examen por imágenes que mejor confirma la presencia de bronquiectasia?",
  o=["Tomografía axial computarizada.", "Radiografía de tórax.", "Gammagrafía pulmonar.", "Resonancia magnética.", "Ecografía torácica."], k="A",
  c="Las bronquiectasias son dilataciones irreversibles de los bronquios por inflamación e infección crónica (fibrosis quística, discinesia ciliar, infecciones graves, tuberculosis, aspergilosis broncopulmonar alérgica). La prueba de elección para confirmarlas es la tomografía computarizada de alta resolución (TCAR) de tórax, que muestra el signo del anillo de sello (bronquio de diámetro mayor que la arteria acompañante), la ausencia de adelgazamiento bronquial hacia la periferia, el engrosamiento de las paredes y los bronquios visibles a menos de 1 cm de la pleura. La radiografía puede ser normal o mostrar líneas en «vías de tranvía» y quistes; la RM no ofrece buena resolución del parénquima pulmonar. Clínica: tos crónica con esputo purulento abundante («tazas de esputo»), hemoptisis y sibilancias. Tratamiento: fisioterapia respiratoria, antibióticos en exacerbaciones y macrólidos a largo plazo en exacerbadores frecuentes.",
  f="ERS, guía de bronquiectasias en adultos (2017); BTS, guía de bronquiectasias (2019); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cirugia", cat=None, tema="Diagnóstico de la insuficiencia venosa periférica", año=2016, ext=False,
  e="¿Cuál es el método ideal para el diagnóstico de insuficiencia venosa periférica?",
  o=["Doppler manual.", "Pletismografía.", "Flebografía.", "Prueba de Perthes.", "Prueba de Brodie-Trendelenburg."], k="A",
  c="La insuficiencia venosa crónica se sospecha por la clínica (várices, edema, hiperpigmentación, lipodermatoesclerosis y úlceras), pero se confirma y se caracteriza con ecografía Doppler venosa (dúplex): evalúa el sistema superficial, profundo y perforante, localiza el punto de reflujo y detecta trombos. El Doppler de onda continua manual es una versión simple. Las pruebas clínicas de Trendelenburg (competencia de la unión safenofemoral), Perthes (permeabilidad del sistema profundo) y Brodie-Trendelenburg (incompetencia de perforantes) se usaban antes y hoy tienen valor histórico. La flebografía es invasiva y la pletismografía mide la función de la bomba muscular. La clasificación CEAP define estadio clínico (C0-C6), etiología, anatomía y fisiopatología. Tratamiento: compresión (20-30 mmHg), ablación endovenosa (láser o radiofrecuencia) o escleroterapia.",
  f="ESVS, guía de enfermedad venosa crónica (2022); SVS/AVF (2011); Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="endocrinologia", cat=None, tema="Hipertensión paroxística con masa suprarrenal", año=2017, ext=False,
  e="Varón de 35 años acude a emergencia por presentar crisis hipertensiva con valores de presión arterial superior a 200/100 mmHg, situación que se ha repetido en varias oportunidades. Antecedente de presentar dolor abdominal, por lo cual le solicitaron una TAC abdominal encontrándose una tumoración sobre el riñón izquierdo. ¿Qué examen solicita para precisar el diagnóstico?",
  o=["Metanefrinas urinarias.", "Eritropoyetina.", "Cortisol plasmático.", "Aldosterona.", "Renina sérica."], k="A",
  c="La combinación de crisis hipertensivas paroxísticas y una masa suprarrenal sugiere feocromocitoma, tumor de las células cromafines que produce adrenalina y noradrenalina. Se confirma con metanefrinas fraccionadas en orina de 24 horas o, mejor, con metanefrinas libres en plasma, más sensibles que las catecolaminas y el ácido vanilmandélico; se evitan falsos positivos suspendiendo antidepresivos tricíclicos, levodopa y paracetamol cuando se mide por ciertos métodos. Después se localiza con TC o RM y, si es extra-suprarrenal o múltiple, con gammagrafía MIBG o PET-DOTATATE. Regla de oro: bloquear primero con alfa-bloqueo (fenoxibenzamina, doxazosina) 10-14 días antes de la cirugía y luego betabloqueo; el betabloqueo aislado puede provocar una crisis hipertensiva. Se asocia a MEN 2, von Hippel-Lindau y neurofibromatosis tipo 1: tamizaje genético en todos.",
  f="Endocrine Society, feocromocitoma y paraganglioma (Lenders 2014); Harrison Principios de Medicina Interna 22.ª ed.",
  nota="Pregunta repetida en RM 2014 y RM 2017 (misma clave).")

Q(a="cardiologia", cat=None, tema="Infarto de cara inferior (derivaciones II, III, aVF)", año=2017, ext=False,
  e="Varón de 60 años presenta dolor precordial intenso hace 2 horas. Antecedente de HTA y fumador desde hace 20 años. Examen: sudoroso, pálido. PA: 120/60 mmHg. FC: 60 x min. FR: 24 x min. Ruidos cardiacos arrítmicos. EKG: segmento ST con supradesnivel y ondas T negativas y simétricas en DII, DIII y aVF. Tiene diagnóstico probable de IMA. ¿Qué cara del corazón está comprometida?",
  o=["Inferior.", "Anterior.", "Lateral.", "Septal.", "Posterior."], k="A",
  c="Las derivaciones DII, DIII y aVF «miran» la pared inferior (diafragmática) del ventrículo izquierdo, que depende de la arteria coronaria derecha en el 80 % de las personas (dominancia derecha) y de la circunfleja en el resto. Las ondas T negativas simétricas junto con el supradesnivel del ST indican infarto en evolución. La bradicardia relativa (60 lpm) y la hipotensión pueden deberse a compromiso del nodo sinusal o AV, o al reflejo de Bezold-Jarisch. En todo infarto inferior hay que registrar derivaciones derechas (V3R, V4R): una elevación del ST de ≥ 1 mm en V4R indica infarto del ventrículo derecho, que cursa con hipotensión, ingurgitación yugular y campos pulmonares limpios, y se trata con volumen, no con nitratos. Reperfusión con angioplastia primaria en menos de 120 minutos.",
  f="ESC, síndromes coronarios agudos (2023); Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Fibrilación auricular como causa de embolia", año=2017, ext=False,
  e="¿Cuál es la causa más frecuente de embolias de origen cardiaco?",
  o=["Enfermedad mitral con fibrilación auricular.", "Endocarditis infecciosa subaguda.", "Infarto agudo de miocardio.", "Insuficiencia aórtica.", "Miocardiopatía dilatada."], k="A",
  c="En el corazón, el trombo se forma por estasis (fibrilación auricular, estenosis mitral, aneurisma ventricular, miocardiopatía dilatada), por lesión endotelial (infarto reciente con trombo mural, endocarditis) o por hipercoagulabilidad. La causa más frecuente de embolia cardiogénica es la fibrilación auricular, sobre todo cuando coexiste estenosis mitral reumática (riesgo de ictus 17 veces mayor que en población sin FA). El ictus cardioembólico suele ser de inicio súbito, con déficit máximo desde el inicio, y a menudo hemorrágico por transformación. Es útil recordar que la causa más frecuente de ictus isquémico en general es la aterotrombosis de arterias grandes. Prevención: anticoagulación oral con un anticoagulante directo (o warfarina con INR 2-3 en estenosis mitral moderada a grave y prótesis mecánicas) y cierre de la orejuela izquierda en pacientes con contraindicación.",
  f="ESC/EACTS, guía de fibrilación auricular (2024); AHA/ASA, prevención secundaria del ictus (2021)",
  nota="Pregunta repetida en RM 2016 y RM 2017 (misma clave).")

Q(a="ciencias_basicas", cat="Anatomía", tema="Irrigación de los nodos sinusal y auriculoventricular", año=2017, ext=False,
  e="En la mayoría de los casos, los nodos sinusal y auriculoventricular están irrigados por la arteria:",
  o=["Coronaria derecha.", "Coronaria izquierda.", "Ramas de la circunfleja.", "Interventricular.", "Marginal."], k="A",
  c="El nodo sinusal recibe su irrigación de la arteria del nodo sinoauricular, que nace de la coronaria derecha en el 55-65 % de los casos y de la circunfleja en el resto. El nodo auriculoventricular se irriga por la arteria del nodo AV, rama de la coronaria derecha en el 80-90 % (dominancia derecha), a nivel de la «crux cordis» donde se unen el surco auriculoventricular y el interventricular posterior. Esto explica por qué los infartos inferiores, por oclusión de la coronaria derecha, se asocian con bradicardia sinusal, bloqueo AV de primer grado o de tipo Wenckebach (a menudo transitorio y que responde a atropina) y, menos frecuente, bloqueo completo. En el infarto anterior un bloqueo AV de segundo o tercer grado indica una lesión extensa del tabique y de mal pronóstico.",
  f="Moore Anatomía con orientación clínica 8.ª ed.; Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Shock de bajo gasto cardiaco", año=2017, ext=False,
  e="¿Cuál es el tipo de shock que presenta un paciente con presión arterial media disminuida, pulso filiforme, extremidades frías y llenado capilar lento?",
  o=["Con gasto cardíaco bajo.", "Con resistencia vascular baja.", "Con resistencia vascular alta.", "Mixto.", "Con gasto cardíaco alto."], k="A",
  c="Pulso filiforme, extremidades frías y llenado capilar lento reflejan una perfusión periférica disminuida por vasoconstricción compensadora: se trata de un shock con gasto cardiaco bajo. Esto abarca el shock hipovolémico (hemorragia, deshidratación), el cardiogénico (fallo de bomba) y el obstructivo (embolia pulmonar, taponamiento, neumotórax a tensión), todos con resistencias vasculares sistémicas altas. El shock distributivo (séptico, anafiláctico, neurogénico) tiene gasto cardiaco alto o normal y resistencias bajas: la piel es caliente y el pulso saltón (salvo en fases avanzadas del séptico). Diferenciarlos orienta el tratamiento: volumen en el hipovolémico, inotrópicos y revascularización en el cardiogénico, resolución de la obstrucción en el obstructivo y vasopresores (noradrenalina) con control del foco en el séptico.",
  f="Surviving Sepsis Campaign (2021); ATLS 11.ª ed. (2025); AHA, shock cardiogénico (declaración científica 2017)",
  nota="Pregunta repetida en RM 2014 y RM 2017 (misma clave).")

Q(a="cirugia", cat=None, tema="Hernia diafragmática traumática", año=2017, ext=False,
  e="Varón de 45 años, que sufre herida por arma punzocortante en el 6.º espacio intercostal izquierdo y línea axilar media, presenta disnea severa, cianosis, ingurgitación yugular y presencia de ruidos hidroaéreos en el hemitórax izquierdo. ¿Cuál es el diagnóstico presuntivo?",
  o=["Hernia diafragmática traumática.", "Taponamiento cardiaco.", "Hemotórax.", "Perforación gástrica.", "Neumotórax."], k="A",
  c="Una herida penetrante por debajo del cuarto espacio intercostal (límite del «tórax toracoabdominal») puede lesionar el diafragma, sobre todo a la izquierda porque el hígado protege el derecho. La presión negativa del tórax y la positiva del abdomen favorecen que el estómago, el colon o el epiplón pasen al hemitórax: se oyen ruidos hidroaéreos en el tórax, hay disnea, cianosis por compresión pulmonar y desplazamiento del mediastino (que reduce el retorno venoso, de ahí la ingurgitación yugular). La radiografía muestra asas con aire en el tórax, elevación del hemidiafragma y la sonda nasogástrica enrollada en el tórax. Tratamiento: reparación quirúrgica urgente (laparotomía en trauma agudo, toracotomía en la hernia crónica). No se debe colocar un tubo torácico a ciegas si se sospecha hernia, porque se puede perforar la víscera.",
  f="ATLS, 11.ª ed. (2025); Schwartz Principios de Cirugía 11.ª ed.")

Q(a="cardiologia", cat=None, tema="Fisiopatología del edema pulmonar cardiogénico", año=2017, ext=False,
  e="¿Cuál es la patogenia en el edema pulmonar cardiogénico?",
  o=["Aumento de presión hidrostática.", "Alteración del endotelio vascular.", "Aumento de presión oncótica.", "Alteración de sustancia tensoactiva.", "Colapso alveolar."], k="A",
  c="En el edema pulmonar cardiogénico la falla del ventrículo izquierdo eleva las presiones de llenado: la presión auricular izquierda y luego la presión capilar pulmonar superan los 18-25 mmHg y el trasudado cruza hacia el intersticio y los alvéolos según la ley de Starling (aumento de la presión hidrostática). En el edema no cardiogénico (síndrome de dificultad respiratoria aguda), la lesión del endotelio y del epitelio aumenta la permeabilidad y el líquido es un exudado rico en proteínas, con presiones de enclavamiento normales. La disminución de la presión oncótica (hipoalbuminemia) también causa edema, pero por sí sola rara vez lo produce. Tratamiento: oxígeno, ventilación no invasiva (CPAP/BiPAP), diuréticos de asa IV, vasodilatadores (nitroglicerina) si hay PA adecuada, y tratar la causa (isquemia, arritmia, crisis hipertensiva).",
  f="ESC, insuficiencia cardiaca aguda (2021, actualización 2023); Guyton y Hall Tratado de Fisiología Médica 14.ª ed.")

Q(a="cirugia", cat=None, tema="Prueba ideal para evaluar várices", año=2017, ext=False,
  e="¿Cuál es la prueba ideal de evaluación de las várices?",
  o=["Doppler.", "Pletismografía.", "Flebografía.", "Prueba de Perthes.", "Prueba de Brodie-Trendelenburg."], k="A",
  c="Las várices son venas superficiales dilatadas y tortuosas (> 3 mm) por incompetencia valvular. Se evalúan con ecografía Doppler dúplex en bipedestación, que identifica el vaso con reflujo (safena mayor o menor, perforantes), mide su diámetro y descarta trombosis profunda; es el estudio ideal antes de tratar. Las maniobras clínicas de Trendelenburg y de Perthes orientaban sobre la competencia de las safenas y la permeabilidad del sistema profundo pero han sido desplazadas. La flebografía solo se usa en casos complejos. Factores de riesgo de várices: sexo femenino, embarazo, edad, obesidad, bipedestación prolongada y antecedente familiar. Complicaciones: tromboflebitis superficial, hiperpigmentación, eczema varicoso, lipodermatoesclerosis y úlcera venosa (maléolo medial). El tratamiento incluye compresión, ablación térmica y escleroterapia.",
  f="ESVS, guía de enfermedad venosa crónica (2022); Sabiston Tratado de Cirugía 21.ª ed.",
  nota="Pregunta repetida (RM 2016 y RM 2017).")

Q(a="cirugia", cat=None, tema="Duración de la anticoagulación en tromboflebitis superficial", año=2017, ext=False,
  e="Mujer de 55 años con diagnóstico de várices, que refiere eritema, calor y dolor en las venas afectadas y que pueden palparse como un cordón indurado. ¿Cuántas semanas es aconsejable la anticoagulación?",
  o=["Dos.", "Seis.", "Cuatro.", "Una.", "Tres."], k="B",
  c="La tromboflebitis superficial con un trombo de 5 cm o más en la safena (o a menos de 3 cm de la unión safenofemoral) tiene riesgo de extenderse al sistema profundo y de causar embolia pulmonar. El estudio CALISTO mostró que fondaparinux 2,5 mg subcutáneo al día durante 45 días (unas seis semanas) redujo la trombosis venosa profunda, la embolia pulmonar y la extensión del trombo en un 85 %. Por eso se aconseja anticoagular seis semanas. Alternativas: heparina de bajo peso molecular en dosis profilácticas o intermedias por 4-6 semanas, o rivaroxabán 10 mg al día por 45 días. Si el trombo mide menos de 5 cm, basta con tratamiento sintomático y control ecográfico. Siempre se debe confirmar con eco Doppler la extensión y descartar trombosis venosa profunda concomitante, que se trata como tal por 3 meses.",
  f="ACCP/CHEST, enfermedad tromboembólica venosa (2021); ESVS, guía de enfermedad venosa (2022); CALISTO (NEJM 2010)")

Q(a="neumologia", cat=None, tema="Dosis de enoxaparina en tromboembolia pulmonar", año=2018, ext=False,
  e="Mujer de 50 años, obesa, hipertensa, con antecedente de cáncer de colon, viaja en bus de Tumbes a Lima; al llegar presenta súbitamente dolor torácico, disnea y síncope. Ingresa a emergencia con PA: 120/60 mm Hg, FC: 120 x min, FR: 30 x min, SatO₂: 96 %. Con diagnóstico de tromboembolismo pulmonar, ¿cuál es la dosis de enoxaparina que se debe administrar?",
  o=["1 mg/kg cada 24 horas SC.", "1 mg/kg cada 12 horas EV.", "1 mg/kg cada 24 horas EV.", "1 mg/kg cada 12 horas SC.", "2 mg/kg cada 12 horas EV."], k="D",
  c="La anticoagulación inicial del tromboembolismo pulmonar con inestabilidad ausente se hace con heparina de bajo peso molecular subcutánea: enoxaparina 1 mg/kg cada 12 horas (o 1,5 mg/kg cada 24 horas), que se prefiere a la heparina no fraccionada por su farmacocinética previsible y menor riesgo de sangrado y trombocitopenia. Se ajusta en insuficiencia renal grave (depuración < 30 mL/min: 1 mg/kg cada 24 horas) y se evita en obesidad mórbida sin monitorización de anti-Xa. Tras la fase aguda se continúa con un anticoagulante oral directo (rivaroxabán, apixabán, edoxabán, dabigatrán) o warfarina por al menos 3 meses; en cáncer se prefieren los inhibidores del factor Xa o la HBPM por 6 meses o más. Si hay shock o hipotensión persistente (TEP de alto riesgo) se indica trombólisis sistémica, y la heparina no fraccionada es la elegida.",
  f="ESC, guía de embolia pulmonar (2019); ASH, tratamiento de la enfermedad tromboembólica venosa (2020); ACCP/CHEST (2021)")
